1	package hotel.reservations;
2	
3	import static org.junit.jupiter.api.Assertions.assertEquals;
4	import static org.junit.jupiter.api.Assertions.assertNull;
5	import static org.junit.jupiter.api.Assertions.assertThrows;
6	import static org.junit.jupiter.api.Assertions.assertTrue;
7	
8	import hotel.EmptyDatabase;
9	import hotel.documents.ReservationReceipt;
10	import hotel.messages.EmailSender;
11	import hotel.messages.Message;
12	import hotel.messages.SentMessages;
13	import hotel.rooms.Rooms;
14	import java.math.BigDecimal;
15	import java.time.LocalDate;
16	import java.util.List;
17	import org.junit.jupiter.api.AfterEach;
18	import org.junit.jupiter.api.Test;
19	
20	class ReservationServiceTest {
21	
22	    private final EmptyDatabase database = new EmptyDatabase();
23	    private final SentMessages sentMessages = new SentMessages(database.dataSource());
24	    private final ReservationService service = new ReservationService(
25	            new Rooms(database.dataSource()), new ReservationStore(database.dataSource()), new PriceCalculator(),
26	            new EmailSender(sentMessages));
27	
28	    @AfterEach
29	    void closeDatabase() {
30	        database.close();
31	    }
32	
33	    private static NewReservation stay(int roomNumber, String checkIn, String checkOut, int guests, RatePlan plan) {
34	        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
35	        return new NewReservation(
36	                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), guests, plan);
37	    }
38	
39	    private static ErrorCode errorOf(Runnable action) {
40	        return assertThrows(HotelException.class, action::run).errorCode();
41	    }
42	
43	    @Test
44	    void aNewReservationIsPendingWithItsPrice() {
45	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
46	
47	        assertEquals(ReservationStatus.PENDING, reservation.status());
48	        assertEquals(new BigDecimal("749.70"), reservation.price().total());
49	        assertNull(reservation.refund());
50	    }
51	
52	    @Test
53	    void refusesInvalidStays() {
54	        assertEquals(ErrorCode.INVALID_REQUEST,
55	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-10", 2, RatePlan.STANDARD))));
56	        assertEquals(ErrorCode.INVALID_REQUEST,
57	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 0, RatePlan.STANDARD))));
58	        assertEquals(ErrorCode.ROOM_NOT_FOUND,
59	                errorOf(() -> service.create(stay(999, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD))));
60	        assertEquals(ErrorCode.CAPACITY_EXCEEDED,
61	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 3, RatePlan.STANDARD))));
62	    }
63	
64	    @Test
65	    void aRoomCannotBeBookedTwiceForTheSameNight() {
66	        service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
67	
68	        assertEquals(ErrorCode.ROOM_UNAVAILABLE,
69	                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.STANDARD))));
70	        // the check-out day is free for the next guest, and another room is free on the same nights
71	        service.create(stay(201, "2027-03-13", "2027-03-15", 2, RatePlan.STANDARD));
72	        service.create(stay(202, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
73	    }
74	
75	    @Test
76	    void aCancelledReservationFreesTheRoom() {
77	        Reservation first = service.create(stay(301, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
78	        service.cancel(first.id());
79	
80	        service.create(stay(301, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
81	    }
82	
83	    @Test
84	    void confirmingSendsTheReceiptByEmail() {
85	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
86	
87	        service.confirm(reservation.id());
88	
89	        assertEquals(ReservationStatus.CONFIRMED, service.find(reservation.id()).status());
90	        List<Message> sent = sentMessages.all();
91	        assertEquals(1, sent.size());
92	        assertEquals("EMAIL", sent.get(0).channel());
93	        assertEquals("ana@example.com", sent.get(0).to());
94	        assertEquals("Reserva confirmada - Pousada Maré Alta", sent.get(0).subject());
95	        assertTrue(sent.get(0).body().contains("Desconto: R$ 37,48"));
96	        assertTrue(sent.get(0).body().contains("Total: R$ 212,42"));
97	    }
98	
99	    @Test
100	    void onlyAPendingReservationCanBeConfirmed() {
101	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
102	        service.confirm(reservation.id());
103	
104	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, errorOf(() -> service.confirm(reservation.id())));
105	        assertEquals(1, sentMessages.all().size());
106	    }
107	
108	    @Test
109	    void cancellingGivesTheMoneyBackAccordingToTheRatePlan() {
110	        Reservation pending = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
111	        Reservation standard = service.create(stay(102, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
112	        Reservation nonRefundable = service.create(stay(201, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
113	        service.confirm(standard.id());
114	        service.confirm(nonRefundable.id());
115	
116	        assertEquals(new BigDecimal("0.00"), service.cancel(pending.id()).refund());
117	        assertEquals(new BigDecimal("249.90"), service.cancel(standard.id()).refund());
118	        assertEquals(new BigDecimal("0.00"), service.cancel(nonRefundable.id()).refund());
